package com.tabika;
import java.time.LocalDate; import java.util.LinkedHashMap; import java.util.Map; import jakarta.servlet.http.HttpSession; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*;
@Controller public class ReservationController { private final ReservationService service; public ReservationController(ReservationService s){service=s;}
 @GetMapping("/reservation") public String form(@RequestParam(required=false) LocalDate date, Model m){LocalDate d=date==null?LocalDate.now().plusDays(1):date; m.addAttribute("date",d);m.addAttribute("slots",service.available(d));m.addAttribute("reservation",new Reservation());return "reservation";}
 @PostMapping("/reservation") public String submit(@Valid @ModelAttribute Reservation r, BindingResult b, @RequestParam LocalDate date, Model m){if(!b.hasErrors())try{service.reserve(r);return "reservation-complete";}catch(RuntimeException e){b.reject("reservation",e.getMessage());}m.addAttribute("date",date);m.addAttribute("slots",service.available(date));return "reservation";}
 @GetMapping("/admin/reservations") public String admin(HttpSession session, Model m){if(!isStaff(session))return "redirect:/admin/login";return "redirect:/staff/calendar";}
 @GetMapping("/admin/login") public String login(){return "admin-login";}
 @PostMapping("/admin/login") public String login(@RequestParam String loginId,@RequestParam String password,HttpSession s){if("admin".equals(loginId)&&"tabika2026".equals(password)){s.setAttribute("admin",true);return "redirect:/staff/calendar";}return "redirect:/admin/login?error";}
 @GetMapping("/staff/calendar") public String calendar(HttpSession session, Model m){if(!isStaff(session))return "redirect:/admin/login";Map<LocalDate,StaffCalendarDay> days=new LinkedHashMap<>();for(StaffReservation r:service.staffCalendar()){StaffCalendarDay d=days.computeIfAbsent(r.getReservedDate(),k->new StaffCalendarDay(k,0,0));d.setReservationCount(d.getReservationCount()+1);d.setParticipantCount(d.getParticipantCount()+r.getGuestCount());}m.addAttribute("days",days.values());return "staff-calendar";}
 @GetMapping("/staff/reservations") public String daily(@RequestParam LocalDate date,HttpSession session,Model m){if(!isStaff(session))return "redirect:/admin/login";m.addAttribute("date",date);m.addAttribute("reservations",service.staffReservations(date));return "staff-daily-reservations";}
 @PostMapping("/admin/logout") public String logout(HttpSession session){session.invalidate();return "redirect:/admin/login?logout";}
 private boolean isStaff(HttpSession session){return Boolean.TRUE.equals(session.getAttribute("admin"));}}
